internal static class RecoveryTests
{
    internal static void Register(List<(string, Action)> tests)
    {
        void Test(string n, Action a) => tests.Add(("M6: " + n, a));
        Test("npm só remove payload comprovado e preserva índice",()=>{var f=new Fixture();var p=f.Payload();var s=f.Service();var plan=s.Prepare(WindowsCleanupKind.NpmCache,[p]);Assert(plan.EligibleCount==1,plan.Items[0].Decision);var r=s.Run(plan,false,true,plan.Confirmation);Assert(r.State=="Concluída");Assert(!File.Exists(p)&&File.Exists(f.Index));});
        Test("npm simulado não altera conteúdo nem índice",()=>{var f=new Fixture();var p=f.Payload();var s=f.Service();var plan=s.Prepare(WindowsCleanupKind.NpmCache,[p]);var bytes=File.ReadAllBytes(f.Index);var r=s.Run(plan,true);Assert(r.State=="Simulada");Assert(File.Exists(p)&&bytes.SequenceEqual(File.ReadAllBytes(f.Index)));});
        Test("nome hash sem índice vigente não autoriza",()=>{var f=new Fixture();var p=f.Payload();File.WriteAllText(f.Index,"");Assert(f.Service().Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);});
        Test("registro oficial não prova publicidade de pacote com escopo",()=>{var f=new Fixture();var p=f.Payload("https://registry.npmjs.org/@internal/private/-/private-1.0.0.tgz");Assert(f.Service().Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);});
        Test("metadata JSON não é confundida com tarball público",()=>{var f=new Fixture();var p=f.Payload("https://registry.npmjs.org/react");Assert(f.Service().Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);});        Test("tarball com escopo exige prova pública anônima e checksum HTTP",()=>{var f=new Fixture();var p=f.Payload("https://registry.npmjs.org/@public/pkg/-/pkg-1.0.0.tgz");var handler=new PublicHead(File.ReadAllBytes(p));var s=f.Service(new NpmPublicProof(new HttpClient(handler)));var plan=s.Prepare(WindowsCleanupKind.NpmCache,[p]);Assert(plan.EligibleCount==1,plan.Items[0].Decision);Assert(s.Run(plan,true).State=="Simulada"&&handler.Calls==1&&File.Exists(p));});
        Test("prova pública permite remover somente fixture e preserva índice",()=>{var f=new Fixture();var p=f.Payload("https://registry.npmjs.org/@public/pkg/-/pkg-1.0.0.tgz");var handler=new PublicHead(File.ReadAllBytes(p));var s=f.Service(new NpmPublicProof(new HttpClient(handler)));var plan=s.Prepare(WindowsCleanupKind.NpmCache,[p]);Assert(plan.EligibleCount==1);Assert(s.Run(plan,false,true,plan.Confirmation).State=="Concluída"&&!File.Exists(p)&&File.Exists(f.Index)&&handler.Calls==2);});
        Test("mudança de visibilidade pública após prévia bloqueia exclusão",()=>{var f=new Fixture();var p=f.Payload("https://registry.npmjs.org/@public/pkg/-/pkg-1.0.0.tgz");var handler=new PublicHead(File.ReadAllBytes(p));var s=f.Service(new NpmPublicProof(new HttpClient(handler)));var plan=s.Prepare(WindowsCleanupKind.NpmCache,[p]);handler.Status=System.Net.HttpStatusCode.NotFound;Assert(s.Run(plan,false,true,plan.Confirmation).State=="Não executada"&&File.Exists(p)&&handler.Calls==2);});        Test("HEAD sem Content-Length exige checksum público exato",()=>{var f=new Fixture();var p=f.Payload("https://registry.npmjs.org/@public/pkg/-/pkg-1.0.0.tgz");var handler=new PublicHead(File.ReadAllBytes(p)){MissingLength=true};Assert(f.Service(new NpmPublicProof(new HttpClient(handler))).Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==1);handler.WrongHash=true;Assert(f.Service(new NpmPublicProof(new HttpClient(handler))).Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);});
        Test("packument público sem escopo tem origem e estrutura verificadas",()=>{var f=new Fixture();var p=f.ContentBytes("https://registry.npmjs.org/example",System.Text.Encoding.UTF8.GetBytes("{\"name\":\"example\",\"dist-tags\":{\"latest\":\"1.0.0\"},\"versions\":{\"1.0.0\":{\"name\":\"example\",\"version\":\"1.0.0\"}}}"));var s=f.Service();var plan=s.Prepare(WindowsCleanupKind.NpmCache,[p]);Assert(plan.EligibleCount==1,plan.Items[0].Decision);Assert(s.Run(plan,false,true,plan.Confirmation).State=="Concluída"&&!File.Exists(p)&&File.Exists(f.Index));});
        Test("JSON de configuração não se disfarça de packument",()=>{var f=new Fixture();var p=f.ContentBytes("https://registry.npmjs.org/example",System.Text.Encoding.UTF8.GetBytes("{\"name\":\"example\",\"authToken\":\"private\",\"versions\":{},\"dist-tags\":{}}"));Assert(f.Service().Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);});
        Test("nome ou versões de packument divergentes são preservados",()=>{var f=new Fixture();var p=f.ContentBytes("https://registry.npmjs.org/example",System.Text.Encoding.UTF8.GetBytes("{\"name\":\"different\",\"dist-tags\":{\"latest\":\"1\"},\"versions\":{\"1\":{\"name\":\"different\",\"version\":\"1\"}}}"));Assert(f.Service().Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);});        Test("HTTP privado não vira regenerável mesmo com índice local",()=>{var f=new Fixture();var p=f.Payload("https://registry.npmjs.org/@private/pkg/-/pkg-1.0.0.tgz");var handler=new PublicHead(File.ReadAllBytes(p)){Status=System.Net.HttpStatusCode.NotFound};Assert(f.Service(new NpmPublicProof(new HttpClient(handler))).Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);});
        Test("HEAD com tamanho ou checksum divergente preserva tarball",()=>{foreach(bool length in new[]{true,false}){var f=new Fixture();var p=f.Payload("https://registry.npmjs.org/@public/pkg/-/pkg-1.0.0.tgz");var handler=new PublicHead(File.ReadAllBytes(p)){WrongLength=length,WrongHash=!length};Assert(f.Service(new NpmPublicProof(new HttpClient(handler))).Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);}});
        Test("redirecionamento HTTP é recusado sem seguir outro servidor",()=>{var f=new Fixture();var p=f.Payload("https://registry.npmjs.org/@public/pkg/-/pkg-1.0.0.tgz");var handler=new PublicHead(File.ReadAllBytes(p)){Status=System.Net.HttpStatusCode.Redirect};Assert(f.Service(new NpmPublicProof(new HttpClient(handler))).Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0&&handler.Calls==1);});
        Test("ETag fraco é inconclusivo e preserva conteúdo",()=>{var f=new Fixture();var p=f.Payload("https://registry.npmjs.org/@public/pkg/-/pkg-1.0.0.tgz");var handler=new PublicHead(File.ReadAllBytes(p)){Weak=true};Assert(f.Service(new NpmPublicProof(new HttpClient(handler))).Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);});
        Test("prova pública expirada é consultada novamente",()=>{var f=new Fixture();var p=f.Payload("https://registry.npmjs.org/@public/pkg/-/pkg-1.0.0.tgz");var handler=new PublicHead(File.ReadAllBytes(p));var clock=new WindowsCleanupTests.Clock();var s=f.Service(new NpmPublicProof(new HttpClient(handler),clock));var plan=s.Prepare(WindowsCleanupKind.NpmCache,[p]);Assert(plan.EligibleCount==1);clock.Now=clock.Now.AddMinutes(6);handler.Status=System.Net.HttpStatusCode.NotFound;Assert(s.Run(plan,true).State!="Simulada"&&File.Exists(p)&&handler.Calls==2);});        Test("origem privada npm é preservada",()=>{var f=new Fixture();var p=f.Payload("https://internal.example/package.tgz");Assert(f.Service().Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);});
        Test("URL com credenciais ou query é preservada",()=>{foreach(var url in new[]{"https://registry.npmjs.org/a?token=x","https://user:pass@registry.npmjs.org/a"}){var f=new Fixture();var p=f.Payload(url);Assert(f.Service().Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);}});
        Test("checksum do índice inválido bloqueia",()=>{var f=new Fixture();var p=f.Payload();File.WriteAllText(f.Index,File.ReadAllText(f.Index).Replace("make-fetch","fake-fetch"));Assert(f.Service().Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);});
        Test("conteúdo alterado preservando tamanho é bloqueado",()=>{var f=new Fixture();var p=f.Payload();var b=File.ReadAllBytes(p);b[0]++;File.WriteAllBytes(p,b);Assert(f.Service().Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);});
        Test("índice alterado após prévia bloqueia remoção",()=>{var f=new Fixture();var p=f.Payload();var s=f.Service();var plan=s.Prepare(WindowsCleanupKind.NpmCache,[p]);File.AppendAllText(f.Index,"\ninvalid");Assert(s.Run(plan,false,true,plan.Confirmation).State=="Não executada");Assert(File.Exists(p));});
        Test("índice em uso impede remoção",()=>{var f=new Fixture();var p=f.Payload();var s=f.Service();var plan=s.Prepare(WindowsCleanupKind.NpmCache,[p]);using var open=new FileStream(f.Index,FileMode.Open,FileAccess.Read,FileShare.Read);Assert(s.Run(plan,false,true,plan.Confirmation).State=="Não executada");Assert(File.Exists(p));});
        Test("payload em uso impede remoção",()=>{var f=new Fixture();var p=f.Payload();var s=f.Service();var plan=s.Prepare(WindowsCleanupKind.NpmCache,[p]);using var open=new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.Read);Assert(s.Run(plan,false,true,plan.Confirmation).State=="Não executada");Assert(File.Exists(p));});
        Test("JSON inválido no índice produz bloqueio",()=>{var f=new Fixture();var p=f.Payload();f.WriteIndex("[]");Assert(f.Service().Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);});
        Test("cache com Git ou E2.5 permanece protegido",()=>{foreach(var marker in new[]{".git","E2.5"}){var f=new Fixture();var p=f.Payload();File.WriteAllText(Path.Combine(f.Root,marker),"protect");Assert(f.Service().Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);}});
        Test("bucket com checksum válido em caminho errado é bloqueado",()=>{var f=new Fixture();var p=f.Payload();var renamed=f.Index+"a";File.Move(f.Index,renamed);Assert(f.Service().Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);});
        Test("ADS do payload impede limpeza npm",()=>{var f=new Fixture();var p=f.Payload();File.WriteAllText(p+":private","protected");Assert(f.Service().Prepare(WindowsCleanupKind.NpmCache,[p]).EligibleCount==0);});
        Test("ausência de confirmação mantém cache intacto",()=>{var f=new Fixture();var p=f.Payload();var s=f.Service();var plan=s.Prepare(WindowsCleanupKind.NpmCache,[p]);try{s.Run(plan,false);throw new Exception("Confirmou sozinho");}catch(IOException){}Assert(File.Exists(p));});
        Test("medição física exclui subescopos do pai",()=>{string root=@"C:\fixture\recovery";var fs=new FakeFs(root);fs.File("parent.bin",10);fs.Directory("child");fs.File(@"child\data.bin",20);var r=new RecoveryInvestigationService(fs).Measure([Scope(root),Scope(root+@"\child")]);Assert(r.IdentifiedPhysicalBytes==30&&r.Groups.Single(g=>g.Path==root).PhysicalBytes==10&&r.Groups.Sum(g=>g.Files)==2);});
        Test("medição inacessível é parcial sem zero confirmado",()=>{string root=@"C:\fixture\recovery";var fs=new FakeFs(root);fs.Denied.Add(root);var r=new RecoveryInvestigationService(fs).Measure([Scope(root)]);Assert(r.Groups.Single().Partial&&r.Groups.Single().Issues>0&&r.ConfirmedBytes==0);});
        Test("junction e link não entram na medição nem na recuperação",()=>{string root=@"C:\fixture\recovery";var fs=new FakeFs(root);fs.Directory("junction",FileAttributes.ReparsePoint);fs.File(@"junction\hidden.bin",999);fs.File("link.bin",10,FileAttributes.ReparsePoint);var r=new RecoveryInvestigationService(fs).Measure([Scope(root)]);Assert(r.IdentifiedPhysicalBytes==0&&r.Groups.Single().SkippedLinks==2&&!fs.Visited.Contains(root+@"\junction"));});
        Test("cancelamento preserva estado parcial da investigação",()=>{string root=@"C:\fixture\recovery";var fs=new FakeFs(root);using var c=new CancellationTokenSource();c.Cancel();var r=new RecoveryInvestigationService(fs).Measure([Scope(root)],token:c.Token);Assert(r.Cancelled&&r.ConfirmedBytes==0);});
        Test("alocação desconhecida não se torna espaço recuperável",()=>{string root=@"C:\fixture\recovery";var fs=new FakeFs(root);fs.File("a.bin",10);fs.UnknownAllocation=true;var r=new RecoveryInvestigationService(fs).Measure([Scope(root)]);Assert(r.Groups.Single().UnknownAllocation==1&&r.ConfirmedBytes==0&&r.Groups.Single().Physical.StartsWith("≥"));});
        Test("arquivos importantes em Temp não recebem autorização do inventário",()=>{string root=@"C:\fixture\recovery";var fs=new FakeFs(root);foreach(var n in new[]{"important.db","main.rs","private.key","photo.jpg"})fs.File(n,10);var r=new RecoveryInvestigationService(fs).Measure([Scope(root)]);Assert(r.PendingReviewBytes==0&&r.ProtectedBytes==40&&r.ProtectedFileCount==4&&r.ConfirmedBytes==0);});
        Test("mais de 500 mil arquivos únicos preservam ocupação física conhecida",()=>{var r=new Scanner(new LargeFs()).Scan(@"C:\fixture\stream");Assert(r.Files==Scanner.IdentityLimit+1&&r.KnownOccupied==Scanner.IdentityLimit+1&&r.UnknownOccupied==0);});
        Test("arquivo esparso mede alocação física em vez do tamanho lógico",()=>{var f=new Fixture();Directory.CreateDirectory(f.Root);string p=Path.Combine(f.Root,"sparse.bin");using(var file=new FileStream(p,FileMode.CreateNew,FileAccess.ReadWrite,FileShare.None)){if(!SparseNative.DeviceIoControl(file.SafeFileHandle,0x900c4,IntPtr.Zero,0,IntPtr.Zero,0,out _,IntPtr.Zero))throw new Exception("NTFS não permitiu fixture esparsa");file.SetLength(8*1024*1024);}var fs=new WindowsFileSystem();var a=fs.Allocated(p);Assert(fs.Stat(p).Length==8*1024*1024&&a.Bytes is >=0 and <65536);using var locked=LockedFile.Open(p);Assert(locked.AllocationSize()==a.Bytes);});        Test("grupo misto separa espaço protegido do pendente de revisão",()=>{string root=@"C:\fixture\mixed";var fs=new FakeFs(root);fs.File("data.sqlite",20);fs.File("unproven.bin",30);var r=new RecoveryInvestigationService(fs).Measure([Scope(root)]);Assert(r.IdentifiedPhysicalBytes==50&&r.ProtectedBytes==20&&r.PendingReviewBytes==30&&r.ConfirmedBytes==0&&r.ProtectedFileCount==1);});        Test("diagnóstico Docker conta apenas cache não compartilhado e fora de uso",()=>{using var d=JsonDocument.Parse("{\"BuildCache\":[{\"ID\":\"one\",\"InUse\":false,\"Shared\":false,\"Size\":100},{\"ID\":\"active\",\"InUse\":true,\"Shared\":false,\"Size\":200},{\"ID\":\"shared\",\"InUse\":false,\"Shared\":true,\"Size\":300},{\"ID\":\"one\",\"InUse\":false,\"Shared\":false,\"Size\":100}]}");var r=DockerStorageProbe.Parse(d.RootElement);Assert(r.GuestUnusedBuildCacheBytes==100&&r.KnownUnusedRecords==1&&r.HostConfirmedBytes==0);});
        Test("estado Docker ausente ou desconhecido não vira espaço no Windows",()=>{using var d=JsonDocument.Parse("{\"BuildCache\":[{\"ID\":\"one\",\"Size\":100}]} ");var r=DockerStorageProbe.Parse(d.RootElement);Assert(r.UnknownRecords==1&&r.GuestUnusedBuildCacheBytes==0&&r.HostConfirmedBytes==0);using var no=JsonDocument.Parse("{}");Assert(DockerStorageProbe.Parse(no.RootElement).GuestUnusedBuildCacheBytes==null);});
        Test("volumes Docker nunca entram na estimativa de cache",()=>{using var d=JsonDocument.Parse("{\"BuildCache\":[],\"Volumes\":[{\"Name\":\"database\",\"UsageData\":{\"Size\":999999,\"RefCount\":0}}]}");var r=DockerStorageProbe.Parse(d.RootElement);Assert(r.GuestUnusedBuildCacheBytes==0&&r.HostConfirmedBytes==0);});        Test("scanner agrega tamanhos físicos nas pastas",()=>{string root=@"C:\fixture\recovery";var fs=new FakeFs(root);fs.File("a.bin",10);fs.Directory("sub");fs.File(@"sub\b.bin",20);var r=new Scanner(fs).Scan(root);Assert(r.Folders.Single(g=>g.Path==root).KnownOccupied==30&&r.Folders.Single(g=>g.Path.EndsWith("sub")).KnownOccupied==20);});
        Test("histórico compara crescimento e preserva amostras",()=>{var f=new Fixture();var history=new RecoveryHistory(Path.Combine(f.Root,"growth.jsonl"));var first=Report(Scope(f.Root),100);history.Record(first);var second=Report(Scope(f.Root),150);history.Record(second);Assert(second.Groups[0].GrowthBytes==50&&File.ReadAllLines(Path.Combine(f.Root,"growth.jsonl")).Length==2);});
        Test("histórico não inventa tendência com medição parcial",()=>{var f=new Fixture();var history=new RecoveryHistory(Path.Combine(f.Root,"growth.jsonl"));history.Record(Report(Scope(f.Root),100));var second=Report(Scope(f.Root),150);second.Groups[0].Partial=true;history.Record(second);Assert(second.Groups[0].GrowthBytes==null);});
        Test("mudança em subescopo invalida comparação somente do pai afetado",()=>{var f=new Fixture();var history=new RecoveryHistory(Path.Combine(f.Root,"growth.jsonl"));var root=Scope(f.Root);var independent=Scope(f.Root+"-other");var first=Report(root,100);first.Groups.Add(new(){Scope=independent,PhysicalBytes=40});history.Record(first);var next=Report(root,50);next.Groups.Add(new(){Scope=Scope(f.Root+@"\nested"),PhysicalBytes=80});next.Groups.Add(new(){Scope=independent,PhysicalBytes=60});history.Record(next);Assert(next.Groups[0].GrowthBytes==null&&next.Groups[2].GrowthBytes==20);});
        Test("cancelamento npm entre arquivos preserva o próximo payload",()=>{var f=new Fixture();var one=f.Payload();var two=f.Payload("https://registry.npmjs.org/second/-/second-1.0.0.tgz",1);var s=f.Service();var plan=s.Prepare(WindowsCleanupKind.NpmCache,[one,two]);Assert(plan.EligibleCount==2);using var c=new CancellationTokenSource();s.BeforeItemForTest=i=>{if(i==1)c.Cancel();};var r=s.Run(plan,false,true,plan.Confirmation,c.Token);Assert(!File.Exists(one)&&File.Exists(two)&&r.State.Contains("Parcial"));});
        Test("simulação nunca apresenta espaço efetivamente liberado",()=>{var f=new Fixture();var p=f.Payload();var s=f.Service();var r=s.Run(s.Prepare(WindowsCleanupKind.NpmCache,[p]),true);Assert(r.FreeBefore==null&&r.FreeAfter==null&&r.ObservedFreeDelta==null);});
        Test("operação isolada mede espaço livre antes e depois sem atribuir delta",()=>{var f=new Fixture();var p=f.Payload();var s=f.Service();var plan=s.Prepare(WindowsCleanupKind.NpmCache,[p]);var r=s.Run(plan,false,true,plan.Confirmation);Assert(r.FreeBefore>0&&r.FreeAfter>0&&r.FreeDeltaText.Contains("outros processos"));});
    }
    sealed class Fixture
    {
        internal string Root=Path.Combine(Path.GetTempPath(),"Respiro.Missao6.Tests",Guid.NewGuid().ToString("N"));
        internal string Index="";
        string Content => Path.Combine(Root,"cache","content-v2","sha512");
        internal string Payload(string url="https://registry.npmjs.org/example/-/example-1.0.0.tgz",int seed=0)
        {
            var b=Enumerable.Range(0,4096).Select(i=>(byte)(i+seed)).ToArray();b[0]=0x1f;b[1]=0x8b;b[2]=8;b[3]=0;return ContentBytes(url,b);
        }
        internal string ContentBytes(string url,byte[] b)
        {
            var hash=SHA512.HashData(b);string hex=Convert.ToHexString(hash).ToLowerInvariant();string path=NpmCacheProof.Bucket(Content,hex);Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllBytes(path,b);
            string key="make-fetch-happen:request-cache:"+url;
            Index=NpmCacheProof.Bucket(Path.Combine(Root,"cache","index-v5"),Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(key))).ToLowerInvariant());Directory.CreateDirectory(Path.GetDirectoryName(Index)!);
            WriteIndex(JsonSerializer.Serialize(new{key,integrity="sha512-"+Convert.ToBase64String(hash),size=b.Length,time=DateTimeOffset.UtcNow.AddDays(-3).ToUnixTimeMilliseconds(),metadata=new{url}}));return path;
        }
        internal void WriteIndex(string json)=>File.WriteAllText(Index,"\n"+Convert.ToHexString(SHA1.HashData(Encoding.UTF8.GetBytes(json))).ToLowerInvariant()+"\t"+json, new UTF8Encoding(false));
        internal WindowsCleanupService Service(NpmPublicProof? proof=null){var roots=Enum.GetValues<WindowsCleanupKind>().ToDictionary(k=>k,_=>new[]{Path.Combine(Root,"blocked")});roots[WindowsCleanupKind.NpmCache]=[Content];return new(new WindowsCleanupEnvironment(roots,Path.Combine(Root,"journal.jsonl"),true,administrator:false),proof);}
    }
    sealed class PublicHead(byte[] payload) : HttpMessageHandler
    {
        internal int Calls;internal System.Net.HttpStatusCode Status=System.Net.HttpStatusCode.OK;internal bool WrongLength,WrongHash,Weak,MissingLength;
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token)=>Task.FromResult(Send(request,token));
        protected override HttpResponseMessage Send(HttpRequestMessage request,CancellationToken token)
        {
            Calls++;Assert(request.Method==HttpMethod.Head&&request.Headers.Authorization==null&&request.Content==null&&request.RequestUri!.Host=="registry.npmjs.org");
            var response=new HttpResponseMessage(Status){Content=new ByteArrayContent([])};if(!MissingLength)response.Content.Headers.ContentLength=payload.Length+(WrongLength?1:0);
            response.Headers.ETag=new System.Net.Http.Headers.EntityTagHeaderValue("\""+(WrongHash?new string('0',40):Convert.ToHexString(SHA1.HashData(payload)).ToLowerInvariant())+"\"",Weak);response.Headers.Location=new Uri("https://outside.invalid/private");return response;
        }
    }    sealed class LargeFs : IReadOnlyFileSystem
    {
        public DiskEntry Stat(string p)=>new(p,true,FileAttributes.Directory,0,DateTime.UtcNow);
        public bool Exists(string p)=>false;
        public string ProbeUse(string p)=>"Teste";
        public Allocation Allocated(string p)=>new(1,p,1);
        public IEnumerable<DiskEntry> Enumerate(string p){for(int i=0;i<=Scanner.IdentityLimit;i++)yield return new(Path.Combine(p,i+".bin"),false,0,1,DateTime.UtcNow);}
    }
    static class SparseNative
    {
        [System.Runtime.InteropServices.DllImport("kernel32.dll",SetLastError=true)] internal static extern bool DeviceIoControl(Microsoft.Win32.SafeHandles.SafeFileHandle h,uint code,IntPtr input,uint inputSize,IntPtr output,uint outputSize,out uint returned,IntPtr overlapped);
    }    static RecoveryScope Scope(string path)=>new(path,"Teste",RecoveryClass.Review,"Dados ainda não comprovados","Perda de dados","Revisar");
    static RecoveryReport Report(RecoveryScope scope,long bytes)=>new(){Finished=DateTime.Now,Groups=[new(){Scope=scope,PhysicalBytes=bytes}]};
    static void Assert(bool value,string why="Proteção não atendida"){if(!value)throw new Exception(why);}
}